require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';$user=currentUser();$pdo=db();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&verifyCsrf($_POST['csrf']??'')){try{$action=$_POST['action']??'';if($action==='create_profile'){$name=trim($_POST['profile_name']??'');if(!$name)throw new RuntimeException('Profile name is required.');$pdo->prepare('INSERT IGNORE INTO wishlist_profiles(user_id,name) VALUES(?,?)')->execute([$user['id'],$name]);$message='Wishlist profile created.';}elseif($action==='add_candidate'){$profile=(int)($_POST['profile_id']??0);$candidate=$_POST['candidate_id']??'';$check=$pdo->prepare('SELECT id FROM wishlist_profiles WHERE id=? AND user_id=?');$check->execute([$profile,$user['id']]);if(!$check->fetchColumn())throw new RuntimeException('Invalid wishlist profile.');$pdo->prepare('INSERT IGNORE INTO wishlist_items(profile_id,candidate_id) VALUES(?,?)')->execute([$profile,$candidate]);$message='Candidate added to wishlist.';}elseif($action==='remove_candidate'){$pdo->prepare('DELETE wi FROM wishlist_items wi JOIN wishlist_profiles wp ON wp.id=wi.profile_id WHERE wi.profile_id=? AND wi.candidate_id=? AND wp.user_id=?')->execute([(int)$_POST['profile_id'],$_POST['candidate_id']??'',$user['id']]);$message='Candidate removed.';}elseif($action==='email'){$ids=array_values(array_unique(array_filter($_POST['candidate_ids']??[])));$subject=trim($_POST['subject']??'');$body=trim($_POST['body']??'');$profile=(int)($_POST['profile_id']??0);if(!$ids||!$subject||!$body)throw new RuntimeException('Select recipients and enter subject and message.');$all=loadCandidateRecords();$map=[];foreach($all as $c)$map[$c['id']]=$c;$recipients=[];foreach($ids as $id)if(!empty($map[$id]['email']))$recipients[$id]=$map[$id]['email'];if(!$recipients)throw new RuntimeException('Selected candidates do not have usable email addresses.');$dedupe=hash('sha256',$user['id'].'|'.$subject.'|'.$body.'|'.implode(',',array_keys($recipients)));$status=getenv('RESUMEIQ_EMAIL_SEND')==='1'?'sending':'preview';$pdo->beginTransaction();$pdo->prepare('INSERT INTO email_batches(user_id,profile_id,subject,body,recipient_count,status,dedupe_key) VALUES(?,?,?,?,?,?,?)')->execute([$user['id'],$profile?:null,$subject,$body,count($recipients),$status,$dedupe]);$batch=(int)$pdo->lastInsertId();$ri=$pdo->prepare('INSERT INTO email_recipients(batch_id,candidate_id,email,status) VALUES(?,?,?,?)');foreach($recipients as $id=>$email)$ri->execute([$batch,$id,$email,$status==='preview'?'preview':'pending']);$pdo->commit();if($status==='sending'){foreach($recipients as $id=>$email){$ok=@mail($email,$subject,$body,'From: no-reply@resumeiq.local');$pdo->prepare('UPDATE email_recipients SET status=?,sent_at=IF(?,NOW(),NULL),error_text=? WHERE batch_id=? AND candidate_id=?')->execute([$ok?'sent':'failed',$ok?1:0,$ok?null:'mail() failed',$batch,$id]);}$pdo->prepare("UPDATE email_batches SET status='completed' WHERE id=?")->execute([$batch]);$message=count($recipients).' email(s) processed.';}else $message='Preview batch saved for '.count($recipients).' candidate(s). Set RESUMEIQ_EMAIL_SEND=1 only when you are ready for real delivery.';}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=str_contains($e->getMessage(),'Duplicate entry')?'This exact email batch was already created.':$e->getMessage();}}
$profiles=$pdo->prepare('SELECT * FROM wishlist_profiles WHERE user_id=? ORDER BY created_at DESC');$profiles->execute([$user['id']]);$profiles=$profiles->fetchAll();$activeProfile=(int)($_GET['profile']??$_POST['profile_id']??($profiles[0]['id']??0));$allCandidates=loadCandidateRecords();$candidateMap=[];foreach($allCandidates as $c)$candidateMap[$c['id']]=$c;$items=[];if($activeProfile){$s=$pdo->prepare('SELECT wi.candidate_id FROM wishlist_items wi JOIN wishlist_profiles wp ON wp.id=wi.profile_id WHERE wi.profile_id=? AND wp.user_id=?');$s->execute([$activeProfile,$user['id']]);foreach($s->fetchAll() as $row)if(isset($candidateMap[$row['candidate_id']]))$items[]=$candidateMap[$row['candidate_id']];usort($items,fn($a,$b)=>$b['score']<=>$a['score']);}
$activePage='wishlist';$pageTitle='Wishlist · ResumeIQ';$pageStyles='<style>.wish-grid{display:grid;grid-template-columns:260px 1fr;gap:10px;margin-top:12px}.wish-side,.wish-main{padding:17px}.wish-side h2,.wish-main h2{font-size:13px;margin:0}.profile{display:flex;justify-content:space-between;padding:9px;border-radius:9px;margin-top:5px;font-size:10px}.profile.active{background:var(--primary-soft);color:var(--primary)}.add-form{margin-top:15px;padding-top:14px;border-top:1px solid var(--line)}.add-form .btn{width:100%;margin-top:7px}.candidate-table{margin-top:12px}.wish-row{display:grid;grid-template-columns:28px 1fr auto auto;gap:10px;align-items:center;padding:11px;border-bottom:1px solid var(--line)}.wish-row strong{font-size:11px}.wish-row p{font-size:9px;color:var(--muted);margin:3px 0}.mail-box{margin-top:14px;padding:15px;background:#fafafe;border:1px solid var(--line);border-radius:14px}.mail-box h3{font-size:11px;margin:0 0 10px}.mail-box textarea{min-height:100px}.mail-actions{display:flex;gap:8px;margin-top:10px}.notice{padding:10px;border-radius:10px;margin-top:10px;font-size:10px}.notice.ok{background:var(--green-soft);color:var(--green)}.notice.err{background:#fff1f3;color:var(--danger)}@media(max-width:760px){.wish-grid{grid-template-columns:1fr}.wish-row{grid-template-columns:28px 1fr auto}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="page-head"><div><div class="kicker"><i class="fa-solid fa-heart"></i> Curated talent lists</div><h1>Profile wishlists</h1><p>Create a list for each role, select the first five or any candidates, then prepare one controlled email batch.</p></div></section><?php if($message):?><div class="notice ok"><?=htmlspecialchars($message)?></div><?php endif?><?php if($error):?><div class="notice err"><?=htmlspecialchars($error)?></div><?php endif?><section class="wish-grid"><aside class="panel wish-side"><h2>Profiles</h2><?php foreach($profiles as $p):?><a class="profile <?=$activeProfile==(int)$p['id']?'active':''?>" href="?profile=<?=$p['id']?>"><span><?=htmlspecialchars($p['name'])?></span><i class="fa-solid fa-chevron-right"></i></a><?php endforeach?><form class="add-form" method="post"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="create_profile"><input class="control" name="profile_name" placeholder="Senior PHP shortlist" required><button class="btn btn-primary"><i class="fa-solid fa-plus"></i>New profile</button></form><?php if($activeProfile):?><form class="add-form" method="post"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="add_candidate"><input type="hidden" name="profile_id" value="<?=$activeProfile?>"><select class="control" name="candidate_id" required><option value="">Add candidate...</option><?php foreach($allCandidates as $c):$d=candidatePresentation($c);?><option value="<?=htmlspecialchars($c['id'])?>"><?=htmlspecialchars($d['name'])?> · <?=$c['score']?>%</option><?php endforeach?></select><button class="btn"><i class="fa-solid fa-heart"></i>Add to list</button></form><?php endif?></aside><main class="panel wish-main"><h2>Wishlist candidates</h2><?php if(!$activeProfile):?><div class="empty">Create a profile to start a wishlist.</div><?php elseif(!$items):?><div class="empty">No candidates in this profile yet.</div><?php else:?><form method="post" id="mailForm"><input type="hidden" name="csrf" value="<?=csrfToken()?>"><input type="hidden" name="action" value="email"><input type="hidden" name="profile_id" value="<?=$activeProfile?>"><div class="candidate-table"><?php foreach($items as $i=>$c):$d=candidatePresentation($c);?><label class="wish-row"><input type="checkbox" name="candidate_ids[]" value="<?=htmlspecialchars($c['id'])?>"><div><strong><?=htmlspecialchars($d['name'])?></strong><p><?=htmlspecialchars($d['role'])?> · <?=htmlspecialchars($c['email']??'No email')?></p></div><span class="badge"><?=$c['score']?>%</span><span class="tag"><?=htmlspecialchars($c['stage']??'Applied')?></span></label><?php endforeach?></div><div class="mail-box"><h3>Email selected candidates</h3><input class="control" name="subject" placeholder="Interview invitation" required><textarea class="control" name="body" placeholder="Write the candidate-facing message..." required></textarea><div class="mail-actions"><button type="button" class="btn" onclick="document.querySelectorAll('[name=&quot;candidate_ids[]&quot;]').forEach((x,i)=>x.checked=i<5)"><i class="fa-solid fa-ranking-star"></i>Select top 5</button><button class="btn btn-primary"><i class="fa-solid fa-paper-plane"></i>Save/send batch</button></div></div></form><?php endif?></main></section>
